  & .sync-input-container {
    display: flex;
    flex-direction: column;
    position: relative;
    overflow-y: auto;
  }

  & .select-all {
    line-height: var(--hub-floating-button-line-height);
    align-self: end;
    margin-inline: 0;
    margin-block: 0 -20px;
    z-index: 1;
  }

  & .sync-option {
    padding: var(--hub-sync-list-option-padding);
    gap: var(--hub-sync-list-option-gap);
    line-height: normal;

    &:nth-child(even) {
      background-color: var(--color-surface-lower);
    }

    & span {
      overflow: hidden;
      text-overflow: ellipsis;
      color: var(--color-text-base);
      font-weight: 400;
    }

    &:has(input:disabled) {
      pointer-events: none;

      & span {
        color: var(--color-text-muted);
      }
    }
  }
}

#toggleSelectAllInputs(type) {
  const inputs = [...this.querySelectorAll(`#${type} input`)];
  const allSelected = inputs.every(c => c.checked);
  for (const checkbox of inputs.filter(c => !c.disabled)) {
    checkbox.checked = !allSelected;
  }
  this.counterObserver[type] = inputs.filter(c => c.checked).length;
}

const inputs = [...this.querySelectorAll(`#${type} input`)];
const allSelected = inputs.every(c => c.checked);
const selectAllButton =
  type === "addressBooks"
